// Event stream: the live WebSocket (domain events + telemetry) plus durable history from the outbox.
// Nothing here is generated by the browser. Duplicates are dropped by event_id.
import { History, Pause, Play } from "lucide-react";
import { useMemo, useState } from "react";
import { Drawer } from "../../ds/overlay";
import { Badge, Button, Card, Dot, IconButton, SearchInput, Select, Tabs, cx } from "../../ds/ui";
import { call } from "../../lib/api";
import { Page, Restricted, useInspector, useLive, useOperator, type LiveMsg } from "../core";

type Kind = "all" | "event" | "telemetry";
const sev = (m: LiveMsg) => (m.kind === "event" ? "info" : m.level || "info");

export default function Events() { return <Restricted perm="backoffice:read"><Inner /></Restricted>; }

function Inner() {
  const live = useLive();
  const { op } = useOperator();
  const ins = useInspector();
  const [kind, setKind] = useState<Kind>("all");
  const [level, setLevel] = useState("");
  const [source, setSource] = useState("");
  const [q, setQ] = useState("");
  const [history, setHistory] = useState<LiveMsg[]>([]);
  const [loadingHist, setLoadingHist] = useState(false);
  const [open, setOpen] = useState<LiveMsg | null>(null);

  const all = useMemo(() => {
    const ids = new Set(live.messages.map((m) => m._id));
    return [...live.messages, ...history.filter((h) => !ids.has(h._id))];
  }, [live.messages, history]);
  const sources = Array.from(new Set(all.map((m) => (m.kind === "event" ? (m.type || "").split(".")[0] : m.node) || ""))).filter(Boolean).sort();
  const rows = all.filter((m) => (kind === "all" || m.kind === kind) && (!level || sev(m) === level)
    && (!source || (m.kind === "event" ? (m.type || "").startsWith(source) : m.node === source))
    && (!q || JSON.stringify(m).toLowerCase().includes(q.toLowerCase())));

  const loadOlder = async () => {
    setLoadingHist(true);
    try {
      const oldest = history.length ? Math.min(...history.map((h) => h.seq || Infinity)) : undefined;
      const r = await call<any[]>(op.username, `/v1/events?limit=100${oldest && isFinite(oldest) ? `&before_seq=${oldest}` : ""}`);
      setHistory((h) => [...h, ...r.data.map((e) => ({ ...e, _id: `e:${e.event_id}`, _rx: Date.parse(e.occurred_at) }))]);
    } finally { setLoadingHist(false); }
  };

  return (
    <Page title="Event stream" description="Domain events (durable, from the transactional outbox) and operational telemetry (live only), as this console receives them."
      actions={<>
        <span className={cx("flex items-center gap-1.5 text-caption", live.connected ? "text-success" : "text-warning")} role="status"><Dot tone={live.connected ? "success" : "warning"} pulse={live.connected} />{live.connected ? "Connected" : live.reconnecting ? "Reconnecting with backoff…" : "Disconnected"}</span>
        <Button size="sm" variant="secondary" icon={live.paused ? <Play className="h-4 w-4" /> : <Pause className="h-4 w-4" />} onClick={() => live.setPaused(!live.paused)}>{live.paused ? "Resume" : "Pause"}</Button>
        <Button size="sm" variant="secondary" icon={<History className="h-4 w-4" />} loading={loadingHist} onClick={loadOlder}>Load older from outbox</Button>
      </>}>
      <Card className="flex flex-wrap items-end gap-2 p-3">
        <Tabs label="Message kind" value={kind} onChange={setKind} tabs={[{ id: "all", label: "All" }, { id: "event", label: "Domain events" }, { id: "telemetry", label: "Telemetry" }]} />
        <Select label="Severity" hideLabel value={level} onChange={(e) => setLevel(e.target.value)} className="w-36"><option value="">Any severity</option><option value="info">info</option><option value="warn">warning</option><option value="error">error</option></Select>
        <Select label="Source" hideLabel value={source} onChange={(e) => setSource(e.target.value)} className="w-44"><option value="">Any source</option>{sources.map((s) => <option key={s} value={s}>{s}</option>)}</Select>
        <SearchInput className="min-w-[240px] flex-1" value={q} onChange={setQ} placeholder="Reference, correlation id, type…" label="Search events" />
        {live.paused && <Badge tone="warning">paused · new messages held</Badge>}
      </Card>
      <div className="mt-3 overflow-x-auto rounded-lg border border-line bg-surface scrollbar-thin">
        <table className="w-full min-w-[900px] text-body-sm">
          <caption className="sr-only">Event stream</caption>
          <thead className="bg-sunken"><tr>{["Time", "Severity", "Kind", "Type / source", "Reference", "Correlation", "Detail"].map((h) => <th key={h} scope="col" className="border-b border-line px-3 py-2 text-left text-overline uppercase text-fg-muted">{h}</th>)}</tr></thead>
          <tbody>
            {rows.length === 0 && <tr><td colSpan={7} className="px-3 py-10 text-center text-fg-2">Waiting for messages. Make a payment or change a rail scenario.</td></tr>}
            {rows.slice(0, 300).map((m) => {
              const s = sev(m);
              const ref = m.txn_ref || m.payload?.txn_ref;
              return (
                <tr key={m._id} tabIndex={0} onClick={() => setOpen(m)} onKeyDown={(e) => e.key === "Enter" && setOpen(m)} className="cursor-pointer border-b border-line hover:bg-hover">
                  <td className="num whitespace-nowrap px-3 py-1.5 text-fg-2">{new Date(m.occurred_at || m.at || m._rx).toLocaleTimeString()}</td>
                  <td className="px-3 py-1.5"><Badge tone={s === "error" ? "danger" : s === "warn" ? "warning" : "neutral"}>{s === "warn" ? "warning" : s}</Badge></td>
                  <td className="px-3 py-1.5 text-fg-2">{m.kind === "event" ? `event #${m.seq ?? ""}` : "telemetry"}</td>
                  <td className="ref px-3 py-1.5 text-[12.5px] text-fg">{m.kind === "event" ? m.type : `${m.node}.${m.phase}`}</td>
                  <td className="px-3 py-1.5">{ref ? <button onClick={(e) => { e.stopPropagation(); ins.openTxn(ref); }} className="ref whitespace-nowrap text-[12px] text-brand-accent hover:underline">{ref}</button> : <span className="text-fg-muted">—</span>}</td>
                  <td className="ref max-w-[180px] truncate px-3 py-1.5 text-[11.5px] text-fg-2">{m.correlation_id || m.payload?.correlation_id || "—"}</td>
                  <td className="max-w-[320px] truncate px-3 py-1.5 text-fg-2">{m.kind === "event" ? (m.payload?.to ? `${m.payload.from} → ${m.payload.to}` : m.payload?.summary || m.payload?.ref || "") : JSON.stringify(m.detail || {}).slice(0, 80)}</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
      <p className="mt-2 text-caption text-fg-muted">Showing {Math.min(rows.length, 300)} of {rows.length}. Events are de-duplicated by event id; the server may deliver an event more than once by design.</p>
      <Drawer open={!!open} onClose={() => setOpen(null)} title={open ? (open.kind === "event" ? open.type : `${open.node}.${open.phase}`) : ""} description={open?.kind === "event" ? `outbox seq ${open.seq} · ${open.event_id}` : "telemetry (not persisted)"}>
        <pre className="overflow-x-auto rounded-md bg-sunken p-3 font-mono text-[12px] text-fg-2">{JSON.stringify(open, (k, v) => (k.startsWith("_") ? undefined : v), 2)}</pre>
        {open && (open.txn_ref || open.payload?.txn_ref) && <IconButton label="Open transaction" className="mt-2 w-auto px-3 text-label text-brand-accent" onClick={() => { const r = open.txn_ref || open.payload?.txn_ref; setOpen(null); ins.openTxn(r!); }}>Open transaction</IconButton>}
      </Drawer>
    </Page>
  );
}
